def merge_config(base: dict, override: dict | None) -> dict:
    """返回合并后的新 dict;不修改入参;override 为 None 时返回 base 的浅拷贝。"""
    result = dict(base)
    if override:
        result.update(override)
    return result

print(merge_config({'model': 'gpt-4o-mini', 'temperature': 0.7}, {'temperature': 0.2}))
