def stream_chunks(text: str, size: int):
    """把长文本按 size 切块逐个 yield(模拟 LLM 流式输出)。"""
    for i in range(0, len(text), size):
        yield text[i:i + size]

for chunk in stream_chunks('流式输出的本质是生成器', 4):
    print(chunk, end='|')
