import json

TOOLS = {
    'get_weather': lambda city: f'{city}:晴,25°C(示意数据)',
}

def agent_turn(user_input: str, tell_model):
    """tell_model 是模型的替身:返回『工具调用意图』的 JSON(模拟 function calling)。"""
    intent = tell_model(user_input)   # 如 {'tool':'get_weather','args':{'city':'北京'}}
    tool = TOOLS.get(intent['tool'])
    if not tool:
        return '未知工具: ' + intent['tool']   # 模型点名了不存在的工具:回喂错误让它自愈
    return tool(**intent['args'])

print(agent_turn('北京天气怎么样', lambda q: {'tool': 'get_weather', 'args': {'city': '北京'}}))
# 思考:模型『执行』工具了吗?如果 tool 抛异常,循环该怎么把错误喂回去?
